module div_8bit(
    input clk, input rst, input sign, input [7:0] dividend, input [7:0] divisor, input opn_valid, input res_ready,
    output res_valid, output [15:0] result
);
    localparam IDLE = 1'b0;
    localparam DIVIDE = 1'b1;

    reg res_valid_reg;
    reg start_cnt;
    reg [3:0] cnt;
    reg [8:0] neg_divisor;
    reg dividend_sign;
    reg divisor_sign;
    reg [7:0] dividend_abs;
    reg [7:0] divisor_abs;
    reg [17:0] SR;
    wire [9:0] sub_result;
    wire carry_out;
    wire mux_out;
    assign sub_result = {SR[17:9], 1'b0} + {neg_divisor[8], neg_divisor};
    assign carry_out = ~sub_result[9];
    assign mux_out = (sub_result[8:0] & {9{carry_out}}) | (sub_result[8:0] & ~{9{carry_out}});
    always_comb begin
        case(cnt)
            4'h0: SR[17:0] = {dividend_abs, 9'b0};
            default: SR[17:0] = {mux_out, SR[17:1]};
        endcase
    end

    always @(posedge clk or posedge rst) begin
        if(rst) begin
            res_valid_reg <= 1'b0;
            start_cnt <= 1'b0;
            cnt <= 4'b0;
            neg_divisor <= 9'b0;
            dividend_sign <= 1'b0;
            divisor_sign <= 1'b0;
            dividend_abs <= 8'b0;
            divisor_abs <= 8'b0;
        end else begin
            if(opn_valid && !res_valid_reg) begin
                dividend_sign <= sign ? dividend[7] : 1'b0;
                divisor_sign <= sign ? divisor[7] : 1'b0;
                dividend_abs <= sign ? (dividend[7] ? (~dividend + 1'b1) : dividend) : dividend;
                divisor_abs <= sign ? (divisor[7] ? (~divisor + 1'b1) : divisor) : divisor;
                SR <= {dividend_abs, 9'b0};
                neg_divisor <= ~(divisor_abs) + 1'b1;
                cnt <= 4'b1;
                start_cnt <= 1'b1;
            end else if(start_cnt) begin
                if(cnt[3]) begin
                    cnt <= 4'b0;
                    start_cnt <= 1'b0;
                    SR <= {mux_out, SR[17:1]};
                end else begin
                    cnt <= cnt + 1'b1;
                    SR <= {mux_out, SR[17:1]};
                end
            end
        end
    end
    always @(posedge clk or posedge rst) begin
        if(rst) begin
            res_valid_reg <= 1'b0;
        end else begin
            if(cnt == 4'h8) begin
                res_valid_reg <= 1'b1;
            end else if(res_valid_reg && res_ready) begin
                res_valid_reg <= 1'b0;
            end else begin
                res_valid_reg <= res_valid_reg;
            end
        end
    end
    assign res_valid = res_valid_reg;
    assign result = SR[17:0];
endmodule
